import functools


def 把门(fn):
    @functools.wraps(fn)
    def 包装(*args, **kwargs):
        if args[0] < 0:
            print("不许喂负的")
            return
        return fn(*args, **kwargs)

    return 包装


@把门
def 翻三倍(n):
    print(n * 3)


x = int(input())
y = int(input())
翻三倍(x)
翻三倍(y)
